  CollectionHall_100442_Title = {Text = "Pickman"},
  CollectionHall_100458_Desc = {
    Text = "Kaygılar sönsün, yorgunluk dumanla birlikte savrulup gitsin.\nBurada, ısıtan alevlerin yanı başında, biraz soluklanalım."
