  },
  CollectionHall_117961_Desc = {
    Text = "Ye, Avery! Bak, Avery!\nDelilikle gerçeklik arasında, renkten ve sanattan kurulmuş bir köprü!\nSadece biz buradayız. Sadece biz gerçeği görebiliriz!"
