  },
  CollectionHall_117962_Desc = {
    Text = "O düşünüyor, <Italic:Yazdığım her şiir dizesiyle bir taç yaprağı filizlenecek.>\nSözcükleri yaşamıyla besliyor; son şiir tamamlandığında, geçmişin bahçesine geri dönebilecekler."
