  CollectionHall_117962_LockTip = {
    Text = "Zor zorlukta \"Gül'ün Yaşam Alanı\" özel kaydını Tamamla"
  },
  CollectionHall_117962_Title = {Text = "Son Şiir"},
  CollectionHall_117963_Desc = {
    Text = "Bu yeri terk edip Öte Tarafa Doğru gitmeye karar verdi.\nOna veda et, ama Onu unutma.\nO seni hatırlatacak, O seni izleyecek: o deli, o dâhi ressam ve gece göğünde asılı duran ay."
  },
  CollectionHall_117963_LockTip = {
    Text = "Tamamlandı Zihin Derin Dalışı \"Çarpık Dünya Tablosu\""
  },
  CollectionHall_117963_Title = {
    Text = "Öte Tarafa Doğru"
  },
  CollectionHall_117964_Desc = {
    Text = "Şarkı söyleyin! Dans edin! Bal ve süt ateş ışığında birbirine karışırken, Son yaklaşmakta.\nAyaklarınızla tırmanın, kollarınızı birbirine dolayın, birbirinizin boynunu öpün—Çoğal, Türe! Çünkü Ana Ağaç’ın koruması altında, soyumuzdan bir kalıntı nüsha bir gün merhamet bulacak!"
  },
  CollectionHall_117964_LockTip = {
    Text = "Aşama 7-19’u Tamamla"
  },
  CollectionHall_117964_Title = {
    Text = "Çoğal, Türe!"
  },
  CollectionHall_117965_Desc = {
