  },
  CollectionHall_117967_Desc = {
    Text = "Kraliçe'nin bedeni aşınmış, Aram halkı sarı kumlara sürgün edilmiştir.\nZaman, aralıklardan, ölü ruh tarafından, yüzlerce yıl Aram'ı etkileyememiş olan kaderi tanıklar."
