  CollectionHall_117976_Desc = {
    Text = "Güneş ışığı, kış bahçesinin camından süzülüp Horla’nın yüzüne düşüyor. Işığın içinden geçip uykulu bir Horla bulmaya gidiyor.\nColette onu her uyandırdığında, arkasında mutlaka bir gül saklıyor."
