  },
  CollectionHall_117978_Desc = {
    Text = "Yoksulluktan, açlıktan, hastalıktan ve ihanetten azade bir yer. Yalnızca çiçekler ve şiirlerden oluşan bir Cité; yalnızca onlara ait bir sığınak."
