  },
  CollectionHall_117979_Desc = {
    Text = "İlk perdede bir silah varsa, son perdede mutlaka patlar.\nOnunla yeniden karşılaştığında anlatacağın hikâyeyi çoktan tasarladın.\nBir rüyaydı: parlak bir Düşen Güneş’le başlayıp kapkara bir güneşin düşüşüyle sona eren bir rüya."
  },
  CollectionHall_117979_LockTip = {
