  CollectionHall_117979_Title = {
    Text = "Düşen Güneş"
  },
  CollectionHall_117980_Desc = {
    Text = "Bal döküldü, onurlu konuklar geldi. Lütfen, Remouahe’ye yeni tohumlar getirin! Lütfen, arzuyla mayalanmış tutkuda kendinizi kaybedin!"
  },
  CollectionHall_117980_LockTip = {
