  },
  CollectionHall_117980_Title = {Text = "Tutku Anı"},
  CollectionHall_117981_Desc = {
    Text = "Zaman, hayat, hiçlik, kader.\nTüm o karanlık düşler, o muğlak gerçeklikler, aynı şekilde bir sele karışır; iz bırakmadan silinir, ileriye doğru akar, denize doğru yol alır."
