  },
  CollectionHall_117982_Desc = {
    Text = "Kuma basar, siyah halkalar yaratır. Seni önder, seni tutar; çoraktan fışkıran her şeyi sana emanet eder.\nBu gece, ay büyük ve meçhul bir sırrı gizler. Tek bir dansla sorularını yanıtlar ve seni daha büyük bir muammayla baş başa bırakır."
