  CollectionHall_121154_Title = {Text = "Cennet"},
  CollectionHall_121341_Desc = {
    Text = "\"Prenses\" rolünü tamamen benimsemiştir: artık o \"İlahi Ana\"dır, Denizci Tarikatı'nın kilit varlığı olan \"İlahi Cenin\"i beslemekle görevlendirilmiştir. \nBir zamanlar çaresizce özgürlük arayan bir kızdı; Mythag'ın Murphy'si tarafından belgelenen aynı kaçış yolculuğuna Sona-nyl gemisiyle çıkmıştı. \nAncak iyiliksever koruyuculardan yoksun bir dünyada kader, genç kuğunun asil boynunu acımasızca kırdı. \nÇarpık soy bağı onu soluk aldırmadan sardı; bedeninin ölümü bile kaçış sunamadı. Kendini tekrar tekrar \"Ben asil İlahi Ana'yım\" demeye zorlar; bu ifadeyi yalnızca bir öz telkin ve ikna aracı olarak kullanır. \nGeriye yalnızca itaat kalır, yalnızca boyun eğme zorunluluğu. Sahte kehanetin önünde eğilmek, absürt kadere teslim olmak. Ancak o zaman, varlığının sonsuz acılığından isteksizce tatlı, geçici bir hayal kırıntısının tadını çıkarabilir."
  },
  CollectionHall_121341_LockTip = {
    Text = "\"Murphy: Sahte Doğumlu\"yu uyandır"
  },
  CollectionHall_121341_Title = {
    Text = "Murphy: Sahte Doğumlu"
  },
  CollectionHall_121381_Desc = {
    Text = "Başka bir dünyadan bir hikâye için 1000 palamudu takas ettin.\nKahramanların ve iblis tanrının, gözetişin ve Azim’in hikâyesi.\nÇaresizliğin ve isteksizliğin, eski dostların ve yenilerin hikâyesi.\nBir zamanlar var olmuş bir hikâye."
  },
  CollectionHall_121381_LockTip = {
    Text = "\"Sıram\" Çok Boyutlu Bağlantı Tamamlandı"
  },
  CollectionHall_121381_Title = {
    Text = "Kozmik Han'ın Yankısı"
  },
  CollectionHall_121382_Desc = {
    Text = "Çok, çok uzun bir zaman sonra, nihayet İkiz Kuşlar üzerine bir balad söylenir.\nBu, dirilişle gelen kurtuluşun, birbirine bağlanmış ikiz ruhların hikâyesidir."
  },
  CollectionHall_121382_LockTip = {
    Text = "Düş Diyarı \"Göklerin Ötesinde·Bölüm II\"yi Tamamla"
  },
  CollectionHall_121382_Title = {
    Text = "Kanatsız Kuşların Türküsü"
  },
  CollectionHall_121383_Desc = {
    Text = "Delikanlı, gelip geçici olana biçilen bedeli ödedi.\nŞimdi, yalnızca sessiz asa ona yoldaşlık ediyor.\nGenç kral uykuya dalacak ve düşlerinde, dünyanın sonuyla yüz yüze gelecek."
  },
  CollectionHall_121383_LockTip = {
    Text = "Psyche Derin Dalışı \"Taç Giyme Günü\"nü tamamla"
  },
  CollectionHall_121383_Title = {
    Text = "Sınırsız Keder Diyarı"
  },
  CollectionHall_121384_Desc = {
    Text = "Seni sarıyorlar, sana tapıyorlar, sana eşlik ediyorlar.\nYaratıcı’ya doğru yelken açıyorlar."
  },
  CollectionHall_121384_LockTip = {
    Text = "Aşama 9-11’i Tamamla"
  },
  CollectionHall_121384_Title = {
    Text = "Yaratıcı Tanrıya Yelken Aç"
  },
  CollectionHall_121385_Desc = {
    Text = "Bu, yıkımdan yeniden doğan bir çift kanattır; özgürlük uğruna kurbanla takas edilmiştir.\nKaderin kehaneti yerine gelmiştir. Acı bir pişmanlıkla, kan borçlarının kanla ödeneceğine yemin eder."
  },
  CollectionHall_121385_LockTip = {
    Text = "Düş Diyarı \"Göklerin Ötesinde·Bölüm II\"yi Tamamla"
  },
  CollectionHall_121385_Title = {
    Text = "Fırtına Yükseldiğinde"
  },
  CollectionHall_121386_Desc = {
    Text = "Saçma ve kaotik rüyanın en başından beri, Kaderleriyle yüzleşmeye yazgılıydılar.\nYine de fazlasıyla şey yaşadılar ve fazlasıyla şey tanımladılar.\nİnsan aklının saklayabileceği azamî sağduyuyla, kendi kökenlerine bakmaya karar verdiler: Yüce İrade’ye."
  },
  CollectionHall_121386_LockTip = {
    Text = "Aşama 9-11’i Tamamla"
  },
  CollectionHall_121386_Title = {
    Text = "Kökenin Kader Savaşı"
  },
  CollectionHall_121387_Desc = {
    Text = "Kazanmak, yitirmek, koparmak, Feda Etmek.\nKahraman, bedelin son kırıntısına kadar ödedi ve gizli hazineyi koruma Yetkileri, Onların karşılığı oldu."
  },
  CollectionHall_121387_LockTip = {
    Text = "Aşama 9-13’ü Tamamla"
  },
  CollectionHall_121387_Title = {
    Text = "Bebeksiz Göz"
  },
  CollectionHall_121388_Desc = {
    Text = "Tacını kendi başına koydu; tahtla kendi bileklerini prangaya vurdu.\nBu, kısa ve aldatıcı bir sıcaklıktı; bu, bozulmaya yazgılı geçmiş bir görkemdi."
  },
  CollectionHall_121388_LockTip = {
    Text = "Psyche Derin Dalışı \"Taç Giyme Günü\"nü tamamla"
  },
  CollectionHall_121388_Title = {
    Text = "Genç Kralın Yalnız Yolculuğu"
  },
  CollectionHall_121389_Desc = {
    Text = "Elverişsiz duruma rağmen, dudaklarının kenarında hafif bir gülümseme beliriyor.\n \"Çekme sırası bende!\"\nİster Kozmik Han’da ister Mythag’da olsun, bir desteğin hasar gücünü hafife almak sana pahalıya patlar, Ignatiss!"
  },
  CollectionHall_121389_LockTip = {
    Text = "\"Sıram\" Çok Boyutlu Bağlantı Tamamlandı"
  },
  CollectionHall_121389_Title = {
    Text = "Sıra Bende!"
  },
  CollectionHall_121390_Desc = {
    Text = "Hiçbir tamamlanmış efsane, düşmandan dosta dönüşenler olmadan var olamaz."
  },
  CollectionHall_121390_LockTip = {
    Text = "Zor Aşama 9-10’u Tamamla"
  },
  CollectionHall_121390_Title = {
    Text = "Düşmanlar, Dostlar"
  },
  CollectionHall_121391_Desc = {
    Text = "Bundan böyle, Mythag’ın sayısız öğrencisi ve âlimi arasında bir Koruyucu olarak duracaksın."
  },
  CollectionHall_121391_LockTip = {
    Text = "Zor Aşama 9-11’i Tamamla"
  },
  CollectionHall_121392_Desc = {
    Text = "Biz, ebediyet içinde gelip geçen anlar, azgın bir selde savrulan kum taneleri olabiliriz.\nYine de bizim kıymetli ebediyetimiz bu sıradan dünyadadır; çünkü dünya ne kadar çılgın ve kaotik olursa olsun—\ninsan onuru, aklın parıltısı üzerine inşa edilecektir."
  },
  CollectionHall_121392_LockTip = {
    Text = "Aşama 9-11’i Tamamla"
  },
  CollectionHall_121392_Title = {
    Text = "Ebedi İlahi"
  },
  CollectionHall_121393_Desc = {
    Text = "Maceracılar, masallara başaşağı daldılar; her masal aynıydı, içlerinde canavarlar, şeytanlar, periler ve ötesinde bilinmeyen yaratıklar vardı.\nAma masalın sonunda, o uçucu özgürlüğün ve ele avuca sığmaz özlemlerin ardında, taşımaya mahkûm olduğu sahte bir yürek yatıyor."
  },
  CollectionHall_121393_LockTip = {
    Text = "Düş Diyarı \"Göklerin Ötesinde·Bölüm II\"yi Tamamla"
  },
  CollectionHall_121393_Title = {
    Text = "Yıldızlara Doğru"
  },
  CollectionHall_121394_Desc = {
    Text = "Burası, başka bir evrenin uzaysal yarığında konumlanmış Kozmik Han’dır.\nFarklı evrenleri birbirine bağlayan portal, engin yıldız ışığıyla titreşerek gelişini selamlıyor.\nBir dakika… Biz neredeyiz böyle?"
  },
  CollectionHall_121394_LockTip = {
    Text = "\"Sıram\" Çok Boyutlu Bağlantı Tamamlandı"
  },
  CollectionHall_121394_Title = {
    Text = "Kozmik Han'a Hoş Geldin"
  },
  CollectionHall_121395_Desc = {
    Text = "Mythag’ın Kılıcı bu düelloda zaferini garanti edecek.\nSeninle partnerin arasındaki bağ kırılmaz.\nBir gün kendinizi farklı evrenlerde bulsanız bile bu asla değişmeyecek."
  },
  CollectionHall_121395_LockTip = {
    Text = "\"Sıram\" Çok Boyutlu Bağlantı Tamamlandı"
  },
  CollectionHall_121395_Title = {
    Text = "Mythag'ın Kılıcı!"
  },
  CollectionHall_121396_Desc = {
    Text = "\"Günlük Görevini tamamlamadın mı? Onun yerine bir el Kozmik Kart oynasana?\"\n \"D-Etkisi Yasak Bölgesi’ni temizlemedin mi? Onun yerine bir el Kozmik Kart oynasana?\"\n \"Burası Traphase, Kozmik Kart değil! 1000 palamut toplayacağım, görürsün!\""
  },
  CollectionHall_121396_LockTip = {
    Text = "\"Sıram\" Çok Boyutlu Bağlantı Tamamlandı"
  },
  CollectionHall_121396_Title = {
    Text = "Hadi Kozmik Kart Oynayalım!"
  },
  CollectionHall_121397_Desc = {
    Text = "Lütfen adımı çağır, beni unutulmaya mahkûm edecek şafak doğmadan önce."
  },
  CollectionHall_121397_LockTip = {
    Text = "Zor Aşama 9-11’i Tamamla"
  },
  CollectionHall_121397_Title = {
    Text = "Ex Oblivione @2"
  },
  CollectionHall_121398_Desc = {
    Text = "\"Gel, benimle bir Sözleşme imzala ve bir Kart Ustası ol!\"\nBu başka dünyadan gelen ejderha bakire, sana coşkulu ama akıl karıştırıcı bir davet uzatıyor.\nBu Faz Uzayı anomalisini hızla çözmek için, itaat etmekten başka seçeneğin yok."
  },
  CollectionHall_121398_LockTip = {
    Text = "\"Sıram\" Çok Boyutlu Bağlantı Tamamlandı"
  },
  CollectionHall_121398_Title = {
    Text = "Meyhaneci Ignatiss!"
  },
  CollectionHall_121399_Desc = {
    Text = "Geleceğin gelenleri, ağır bir lütfun yükü altında, şu dipnotla karşılaşacak:\nKahramanın tacından kaçan, kahraman oldu; dostlarını yüreğinde saklayan, birinden gayrı hepsini yitirdi."
  },
  CollectionHall_121399_LockTip = {
    Text = "Psyche Derin Dalışı \"Taç Giyme Günü\"nü tamamla"
  },
  CollectionHall_121399_Title = {
    Text = "Yalnız Yürüyeceğim"
  },
  CollectionHall_121400_Desc = {
    Text = "Rab’den kopmak, Rab’bin önünde durmak, Rab’be meydan okumak.\nHikâyeni kimse bilmez, ama anın dünya ile birlikte sonsuza dek tahammül edecektir."
  },
  CollectionHall_121400_LockTip = {
    Text = "Aşama 9-13’ü Tamamla"
  },
  CollectionHall_121400_Title = {
    Text = "Kör Ahmak Tanrı"
  },
  CollectionHall_121401_Desc = {
    Text = "Her şey anlamını yitirir, ve böylece burada durursun.\nGeçmişte olup biten her şey, senin tarafından tanımlandığı hâliyle, burada durmanın tüm anlamını oluşturur."
  },
  CollectionHall_121401_LockTip = {
    Text = "Aşama 9-13’ü Tamamla"
  },
  CollectionHall_121401_Title = {
    Text = "Varoluşçuluk"
  },
  CollectionHall_121402_Desc = {
    Text = "Bu, Onlara giden fitil yolu; bu, Onlardan uzaklaşan fitil yolu.\nHer şey ayrılmak, bitmek, başlamak üzeredir.\nKapı’nın önündeki siluet, Gümüş Anahtar’ın seni eve götüreceği o uzun bekleyişe çoktan başlamıştır."
  },
  CollectionHall_121402_LockTip = {
    Text = "Aşama 9-13’ü Tamamla"
  },
  CollectionHall_121402_Title = {
    Text = "Onlara Giden Fitil Yolu"
  },
  CollectionHall_121403_Desc = {
    Text = "Onların olasılık iplikleri ayrıldı, birleşti ve Saçılma’ya uğradı.\nTa ki biricik kurtarıcı gelene, ta ki nihayet biricik Son Perde’ye adım atana dek."
  },
  CollectionHall_121403_LockTip = {
    Text = "Zor Aşama 9-10’u Tamamla"
  },
  CollectionHall_121403_Title = {
    Text = "Tek Gerçek Son"
  },
  CollectionHall_121404_Desc = {
    Text = "Genç kral anlaşmayı kabul etti.\n“Ülkem emin ve sağ salim olacak,” dedi."
  },
  CollectionHall_121404_LockTip = {
    Text = "Psyche Derin Dalışı \"Taç Giyme Günü\"nü tamamla"
  },
  CollectionHall_121404_Title = {Text = "Taç Giyme"},
  CollectionHall_121405_Desc = {
    Text = "Bu paramparça uzaysal yarığın içinde bir zamanlar efsanevi Kozmik Meyhane dururdu.\nFarklı evrenleri birbirine bağlayan portallar, her Kart Ustasını karşılayan engin yıldız ışığıyla bir zamanlar parıldardı.\nVe tüm bunların bir zamanlar var olduğunun kanıtı sensin."
  },
  CollectionHall_121405_LockTip = {
    Text = "\"Sıram\" Çok Boyutlu Bağlantı Tamamlandı"
  },
  CollectionHall_121405_Title = {
    Text = "Elveda, Kart Ustası!"
  },
  CollectionHall_121406_Desc = {
    Text = "Yaratıcı sana O'nun Bakışı’nı yöneltti, sen ise O'nun gözünü delici bir darbeyle deldin."
  },
  CollectionHall_121406_LockTip = {
    Text = "Aşama 9-13’ü Tamamla"
  },
  CollectionHall_121406_Title = {
    Text = "Sonun Bakışı"
  },
  CollectionHall_121407_Desc = {
    Text = "Savaşçı. İntikamcı. Köle. Efendi. Tüccar.\nAynı duruş mu? Farklı duruşlar mı? Aynı duruş."
  },
  CollectionHall_121407_LockTip = {
    Text = "Aşama 9-11’i Tamamla"
  },
  CollectionHall_121407_Title = {
    Text = "Çoklu Evren Savaş Şarkısı"
  },
  CollectionHall_121408_Desc = {
    Text = "Büyük bir şey için savaşmadığını biliyorsun.\nDers kırmak için, ödev için, tatlılar için, arkadaşlar için, ocağın sıcaklığı için, boş boş oyalanan saatler için.\nSen sadece sıradan bir insansın, sıradan bir gün uğruna ölen biri."
  },
  CollectionHall_121408_LockTip = {
    Text = "Zor Aşama 9-11’i Tamamla"
  },
  CollectionHall_121408_Title = {
    Text = "Sıradan Bir Günün Şehidi"
  },
  CollectionHall_121409_Desc = {
    Text = "Hayvanlar, tüm yüksek hayvanlar, kaçınılmaz biçimde toplumsal davranışlar tarafından yönetilir.\nO ise, arzusu uyarınca, kendi ayaklarıyla ölüme yürür ve Gerçek’i parçalara ayırır.\nÇılgın, eşsiz bir dâhi; umudu andıran o arsenik tarafından yutulan tüm şuurlu varlıkları kurtuluşa erdirmek için, Yıkım’ı kendi elleriyle getirmeyi tercih eder."
  },
  CollectionHall_121409_LockTip = {
    Text = "Aşama 9-13’ü Tamamla"
  },
  CollectionHall_121409_Title = {
    Text = "Topluluk Davranışının Sökümü"
  },
  CollectionHall_121410_Desc = {
    Text = "Bitimsiz bir acı su akışı, Yüce göklerden O’nun tarafından gönderildi; toplandı, birleşti;\nta ki, etimizle kanımız sarmalanmadan önce geçmeye yazgılı olduğumuz ırmağı oluşturana dek."
  },
  CollectionHall_121410_LockTip = {
    Text = "Düş Diyarı \"Göklerin Ötesinde·Bölüm II\"yi Tamamla"
  },
  CollectionHall_121410_Title = {Text = "Acı Nehir"},
  CollectionHall_121411_Desc = {
    Text = "Onlar, kavuşma umuduyla vedalaştılar.\nZira bu Sevgili’dir; çünkü Sevgili’nin ölümü yazgılı değildir."
  },
  CollectionHall_121411_LockTip = {
