  CollectionHall_126471_Desc = {
    Text = "Mouchette sisin varlığına çoktan alıştı.\nNe kadar yoğun ya da ne kadar öldürücü olursa olsun, hiçbir sis onu şimdiye dek durduramadı.\nBu sefer de farklı olmayacak.\nBu yeni dünyanın sisinden yürüyüp çıkacak ve kendi dünyasına geri dönecek... bedeli ne olursa olsun."
