    Text = "Çok Boyutlu Bağlantı \"Gümüş ve Kanın Vaftizi\"ni Tamamlandı"
  },
  CollectionHall_126471_Title = {
    Text = "Yeni Bir Dünyanın Perdesi Açılırken"
  },
  CollectionHall_126472_Desc = {
    Text = "Her sis perdesi bir gün mutlaka kalkmak zorundadır.\nO an geldiğinde, bir zamanlar sisi yaran çığlıklar susacak, sunaktaki kan yıkanıp gidecektir.\nÇoktan yitip gitmiş ruhlar sonunda huzur bulacak, nihayet gerçek yollarına yönlendirilecekler—\nister ışıltılı yıldızlara, ister aşağıdaki sağlam toprağa doğru olsun."
  },
  CollectionHall_126472_LockTip = {
    Text = "Çok Boyutlu Bağlantı \"Gümüş ve Kanın Vaftizi\"ni Tamamlandı"
  },
  CollectionHall_126472_Title = {
    Text = "Sis Çöktüğünde"
  },
  CollectionHall_126473_Desc = {
    Text = "Kozmos dünyaları doğurdu; dünyalar hayatı doğurdu; hayat, birbirinden sapan yasaları ve inançları doğurdu.\nBu hayatlar çarpıştığında, bu asla basit bir güç ya da irade sınavı değildir.\nBu, iki evrenin çarpışmasıdır—ebediyen paralel, ama kesişmeye zorlanmış."
  },
  CollectionHall_126473_LockTip = {
    Text = "Çok Boyutlu Bağlantı \"Gümüş ve Kanın Vaftizi\"ni Tamamlandı"
  },
  CollectionHall_126473_Title = {
    Text = "İnançların Çatışması"
  },
  CollectionHall_126474_Desc = {
    Text = "Görev bittiğinde, eski benliğimle vedalaşacağım.\nAsla geri dönemeyeceğim geçmişe elveda. Temurahn'a, bir zamanlar olduğum insana elveda.\nSisle örtülü o yeri özleyeceğim.\nSisin çekildiği bu yerde, bu tuhaf, ürkütücü yeni yuvada yeniden başlayacağım."
  },
  CollectionHall_126474_LockTip = {
    Text = "Zor Çok Boyutlu Bağlantı \"Gümüş ve Kanın Vaftizi\"yi Tamamla"
  },
  CollectionHall_126474_Title = {
    Text = "Siste Topraktan Yeniden Doğuş"
  },
  CollectionHall_126475_Desc = {
    Text = "Zalim bir dünyada, tek bir ruh bir anda kül olup gidebilir.\nBu yüzden başkalarına sığınırız: aileye, aşka ve hafızaya.\nBu bağlar, bizi ayakta tutan sessiz bir güç hâline gelir—bu dünyada biraz daha uzun yanmamıza izin veren."
