  CollectionHall_126477_Desc = {
    Text = "Dünyayı kurtarmak hiçbir zaman onun yolu olmadı ve bu, kurtarması gereken bir dünya da değil.\nAma Koruyucu'nun sesini duydu ve burayı kurtarmak için nelerin kurban edildiğini gördü.\nBirinin uğruna hayatını verdiği bir dünya, İmha Edilmemeli.\nEn azından şimdi değil. Ve kesinlikle kendi eliyle değil."
