  CollectionHall_131668_Desc = {
    Text = "Eski ve tuhaf, tuhaf ve eski! Ölü eş, gece yarısı küfünden sürünerek gelir.\nO vefasız zampara, ne cüretkâr, ne zalim—Onu da atarız kazana, kaynaya kaynaya erisin.\nŞekilsiz Tanrıçamız duyar onun çığlığını, Yüzünü yüzer, onu Tükenme’ye sürer!\nGöğsünü yarar, kemiğini alırız; Hanımımızın tahtının önüne sereriz."
