  CollectionHall_133770_Desc = {
    Text = "Merhaba yolcular!\nBahar Festivali yaklaşıyor! Bu neşeli kavuşma ve yeni başlangıçlar mevsiminde, tüm ekibimiz uzun yolculuklarla eve dönen yorgun gezginlere en içten dileklerini sunuyor:\n\nSize mutlu bir Bahar Festivali, neşeli aile buluşmaları, hızlı bir yolculuk ve en iyisi dileriz! <(￣︶￣)↗[GO!]"
