  },
  CollectionHall_89706_Title = {Text = "Corposant"},
  CollectionHall_89968_Desc = {
    Text = "Kıyım, nefret, delilik ve acı; savaş alanında bunlar hiç eksik olmaz. Canavarın poker masasında hayatını ortaya koyarken, sebep olacağı kızıl girdabın nasıl olacağını düşünmelisin."
