  },
  CollectionHall_89969_Desc = {
    Text = "Efsaneye göre, seyrüseferci ölümünden sonra direğin tepesinde mavi-beyaz bir parıltıya dönüşür ve geminin yolculuğuna rehberlik etmeyi sürdürür.\nO, hayatını direğin en tepesinde tutuşturduğunda, acaba dönüşün umut dolu fitil yolunu görebildi mi?"
