  CollectionHall_89969_Title = {
    Text = "St. Elmo'nun Ateşi"
  },
  CollectionHall_89970_Desc = {
    Text = "Nefretin, kan dökmenin ve bitmek bilmeyen çatışmanın yazgısına doğmuştu. Tüm o narin düşleri bir kenara bırakıp bıçakla silahı eline almayı seçtiğinde, kaderin zafer marşı onun için çoktan çalmaya başlamıştı bile. Bir savaşçı olmaya yazgılıydı; nefretini düşmanlarının kanıyla yıkayıp arındıracak, ardından belki görkemli olmayan, ama korkusuz ve pişmansız bir hayat sürecekti."
  },
  CollectionHall_89970_LockTip = {
    Text = "Özel kayıt \"Elworth'un Döneni\"ni tamamla"
  },
  CollectionHall_89970_Title = {
    Text = "Kızıl İntikam"
  },
  CollectionHall_89971_Desc = {
    Text = "Kan kırmızısı batan güneşin altında, kana bulanmış sarı kumlar uzanır.\nGüçlü savaşçı, geceye gömülmek üzere olan savaş alanında dikilir, geçmişin altın alevlerini ve görkemini yad eder.\nSayısız çığlık atan akbaba yükselir, son ışık huzmelerini tıkar. Büyük doğu seferinde, çöl, onunla birlikte gömülmek üzere ona eşlik eden ölümsüzlerle dolup taşar."
  },
  CollectionHall_89971_LockTip = {
    Text = "Zor zorlukta \"Kan ve Kum\" Psişe Derin Dalışı'nı Tamamla"
