  },
  CollectionHall_98502_LockTip = {
    Text = "Psyche Deepdive: \"Ölümsüz Gündönümü\"nde herhangi bir Aşamayı Tamamla"
  },
  CollectionHall_98502_Title = {
    Text = "Sonsuz Yanan Av"
  },
  CollectionHall_98636_Desc = {
    Text = "Kutsal çiğneyiciler, dünyayı yutacak bir Felaket dalgası serbest bırakır, ama yalnız kral kükreyen dalgayla tek başına yüzleşir.\nSaçları rüzgârda savrulur; kemikleri ve kanı, ağırbaşlı bir beyanname gibidir. Alaycı bir gülümsemeyle kendini ölüme ve aya sunar.\nO anda deniz Dondurma’ya uğrar; dolunayın altında baş aşağı asılı duran bir buzul hâline gelir. Her şey susar ve krallığına yeniden sükûnet iner."
  },
  CollectionHall_98636_LockTip = {
    Text = "Zor Yıldız Bölümü 3-10’u Tamamla"
  },
  CollectionHall_98636_Title = {
    Text = "Dolunay Kurbanı"
  },
  CollectionHall_98637_Desc = {
    Text = "Ölüyü pişirmek, ağırbaşlı bir sanattır.\nYemek bıçağı ve spatulayla, yarım kalmış son vasiyetleri sorar; su ve ateşle, son dilekleri yerine getirir.\nHer anı—sıkıntılı, acı verici, buruk—parlak ve mis kokulu bir yemeğe dönüşür; tadılsın, saklansın diye."
  },
  CollectionHall_98637_LockTip = {
    Text = "Yıldız Bölümü 3-11’i Tamamla"
  },
  CollectionHall_98637_Title = {
    Text = "Necrovia'nın Efendisi"
  },
  CollectionHall_98638_Desc = {
    Text = "Bebek çığlık atar, ister, öfkelenir.\nEvrenin merkezidir. Tüm oluşların yazgı yasasıdır.\nBakışının eriştiği her şey hizmet etmeli, itaat etmeli ya da tüketilmelidir."
  },
  CollectionHall_98638_LockTip = {
    Text = "Zor Aşama 6-10’u Tamamla"
  },
  CollectionHall_98638_Title = {
    Text = "Bir Tanrının Doğuşu"
  },
  CollectionHall_98639_Desc = {
    Text = "Her bir ölümü topladığında, tırpanını acımasızca savurmaz.\nEllerinin bir zamanlar sıcak, yüreğinin yumuşak ve merhamet dolu olduğunu hatırlarsın.\nBir ruhun kederini içine çekerken, onunla birlikte ağlar.\nKökleşmiş nefreti tartarken, onun yerine Yargı’yı infaz eder.\nNecrovia'nın Efendisi'nin adıyla ağır bir yemin etti: ölümü kirleten herkes buz gibi, yoğun sise karışıp yok olacak."
  },
  CollectionHall_98639_LockTip = {
    Text = "Yıldız Bölümü 3-11’i Tamamla"
  },
  CollectionHall_98639_Title = {
    Text = "Ölümün Merhameti"
  },
  CollectionHall_98640_Desc = {
    Text = "Etin tatlı lezzeti, kopan tendonların dokusu—bunlar onun en tanıdık ve asla unutamadığı Anılar’dır.\nNecrovia Şehri’nin, yaşayanların gücüyle değil, ölülerin Kurban oluşuyla ayakta kaldığını çoktan anlamıştır.\nBoğazından bir yudum daha Kızıl aşağı süzülür. Gözlerini kapar, her bir eşsiz kokuyu dikkatle tadar, her ruhun tadını hafızasına Damga’lar. Böylece sevdikleri ve halkı, bedeninin içinde ebedi yaşama kavuşur.\nBirlikte olmaları vaat edilmiştir, sonsuza dek."
  },
  CollectionHall_98640_LockTip = {
    Text = "Zor Yıldız Bölümü 3-10’u Tamamla"
  },
  CollectionHall_98640_Title = {
    Text = "Kanlı Söz"
  },
  CollectionHall_98641_Desc = {
    Text = "Kurban Bıçağı ay ışığında aç, parıldayarak titreşir.\nOnu kendi boğazına bastırır; bu bir teslimiyet değil, bildiği tek yolla özgür iradesini kanıtlama çabasıdır."
  },
