  CollectionHall_98642_Desc = {
    Text = "Halkına savaşmayı, öldürmeyi, hayatta kalmayı öğretmişti. Ama onlara kaçmayı asla öğretmedi. Ne üstün sayılardan, ne de ölümün kendisinden.\nBu yüzden kaçmayacaktı.\nBıraksınlar, gelsinler de başını almaya çalışsınlar!\nBiliyordu: Güç, peşine düşenleri yutar. Ve o bununla çoktan barışmıştı."
