  CollectionHall_98645_Desc = {
    Text = "Elton arkasını dönüp uzaklaştığında, bir anlığına yeniden o çocuktur; gökle uçsuz bucaksız mavi denizin birleştiği ufka bakan, her düşe yetecek kadar büyük bir dünyaya bakan çocuk.\nAma artık gerçekleşmiş düşlerin şeklini biliyor. Artık o beyaz kuş diyarına geri götürecek bir harita taşıyor."
