  CollectionHall_98645_Title = {Text = "Anayurt"},
  CollectionHall_98646_Desc = {
    Text = "Zaman geldi, gümüş ay göğe asıldı.\nÇabuk, soğuk parmak uçlarını kaldır ve dans ettir; bu gece bu şöleni kutluyoruz.\nO yolculuğunun sonuna vardı ve biz ona midelerimizle bir cenaze sunuyoruz.\nBir lokma sana, bir lokma bana; bugünden sonra, anılarımızda sonsuza dek yaşayacak."
