  CollectionHall_98648_Desc = {
    Text = "Sevin, dostum♪\nAy ışığının altında, kemikler sessizce çiçek açar♪\nSevgilim gümüş bir tabakta kıpırtısız yatar♪\nTüm konuklar geldi♪Şarkı söyle! Dans et! Şimdi takdis ediyoruz!♪\nAsla cesetler için yas tutma♪Asla ölüler için dua etme♪\nAnıları ellerimde♪gözyaşları dişlerimde♪\nHaydi yutalım ruhunu, ne de tatlı etini♪\nBu ölümcül şölenimizde, sevdiklerin buluştuğu yerde♪"
  },
