  CollectionHall_98650_Desc = {
    Text = "Onu hatırlıyor.\nFırtınada kucağına aldığı çocuğu, vicdanıyla birlikte Uçurum’a verdiği çocuğu—beyaz kuşların süzüldüğü bir yurt düşü uğruna.\nArtık düş gerçek.\nArtık borcun vadesi doldu."
