  },
  CollectionHall_98657_Desc = {
    Text = "Ötekiler, ölümcül cadının fısıltısını duyup dizlerinin üstüne çöktüler. Yalvardılar. Taptılar.\nO değil. Asla.\nO, o gücü gördü ve ona açlık duydu. Bir yakaran olarak değil, bir fatih olarak. Bedeli ne olursa olsun, onu alacaktı.\nVe aldığında, yeniden yükselecekti... Ta ki adı, Filistinlilerin hak iddia ettiği her diyarda gök gürültüsü gibi çınlayana dek."
  },
